const fs = require('fs');

function main() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    const n = input[0];
    const m = input[1];

    if (n >= m) {
        console.log(n - m);
        return;
    }

    const visited = new Array(m + 2).fill(false);
    const queue = [[n, 0]];
    let head = 0;
    visited[n] = true;
    let ans = 0;

    while (head < queue.length) {
        const [location, dist] = queue[head++];

        if (location === m) {
            ans = dist;
            break;
        }

        const next1 = location * 2;
        if (next1 <= m + 1 && !visited[next1]) {
            visited[next1] = true;
            queue.push([next1, dist + 1]);
        }

        const next2 = location - 1;
        if (next2 >= 0 && !visited[next2]) {
            visited[next2] = true;
            queue.push([next2, dist + 1]);
        }
    }

    console.log(ans);
}

